<?php
declare(strict_types=1);
require dirname(__DIR__).'/api/lib.php';require dirname(__DIR__).'/api/supplier-catalog.php';require dirname(__DIR__).'/api/supplier-link.php';
function link_check(bool $ok,string $name): void {if(!$ok)throw new RuntimeException('FAILED '.$name);echo 'PASS '.$name.PHP_EOL;}
// Synthetic public HTML based on the screenshot, not a response fetched from the supplier.
$url='https://meudropbrasil.com/produto/aparador-de-pelos-eletrico-kemei-km-6511-nariz-orelha-recarregavel/';
$html='<html><meta charset="utf-8"><body><header>Pedido de usuário · R$ 999,00</header><main><section><h1>Aparador de Pelos Elétrico Kemei</h1><p>R$ <span>26,00</span></p><li><b>EAN Principal:</b> <code>6955549365117</code></li><p><b>SKU:</b> TEST-LINK-ONLY</p></section></main><form><input type="password" value="DO-NOT-READ"><p>R$ 700,00</p></form></body></html>';
$calls=[];$transport=function($target,$timeout)use(&$calls,$html){$calls[]=$target;return ['status'=>200,'contentType'=>'text/html; charset=utf-8','body'=>$html];};
$r=supplier_read_link($url,$transport);link_check(count($calls)===1&&$r['products'][0]['cost']===2600,'direct link reads R$ 26,00 from product HTML');link_check($r['products'][0]['gtin']==='6955549365117'&&$r['products'][0]['sku']==='TEST-LINK-ONLY','EAN and SKU remain distinct');link_check($r['products'][0]['stock']===null,'unknown stock preserved');link_check(!str_contains(json_encode($r),'DO-NOT-READ'),'password values not returned');
$rich=['@context'=>'https://schema.org','@type'=>'Product','name'=>'Produto JSON-LD','sku'=>'SCHEMA-1','offers'=>['@type'=>'Offer','price'=>'116.00','priceCurrency'=>'BRL']];$r=supplier_html_products('<script type="application/ld+json">'.json_encode($rich).'</script>',$url);link_check($r['products'][0]['cost']===11600&&$r['method']==='json-ld','standard JSON-LD price');
$micro='<div itemscope itemtype="https://schema.org/Product"><h1 itemprop="name">Produto microdados</h1><meta itemprop="sku" content="MICRO-LINK"><div itemscope itemtype="https://schema.org/Offer"><meta itemprop="price" content="59.90"><meta itemprop="priceCurrency" content="BRL"></div></div>';$r=supplier_html_products($micro,$url);link_check($r['products'][0]['cost']===5990&&$r['method']==='microdata','standard microdata');
$og='<meta property="og:type" content="product"><meta property="og:title" content="Produto Open Graph"><meta property="product:price:amount" content="20.90"><meta property="product:price:currency" content="BRL">';$r=supplier_html_products($og,$url);link_check($r['products'][0]['cost']===2090,'Open Graph price');
foreach(['http://meudropbrasil.com/a','https://meudropbrasil.com.evil.example/a','https://meudropbrasil.com@127.0.0.1/a','https://127.0.0.1/a','https://meudropbrasil.com:443/a'] as $bad){$blocked=false;try{supplier_read_link($bad,$transport);}catch(InvalidArgumentException){$blocked=true;}link_check($blocked,'untrusted URL rejected before fetch');}
foreach(['127.0.0.1','10.0.0.1','169.254.169.254','192.168.1.1','::1','fe80::1'] as $ip)link_check(!supplier_public_ip($ip),'private or reserved address denied');
$count=0;$blocked=false;try{supplier_read_link($url,function()use(&$count){$count++;return ['status'=>302,'location'=>'https://evil.example/private'];});}catch(InvalidArgumentException){$blocked=true;}link_check($blocked&&$count===1,'off-site redirect denied before a second fetch');
link_check(supplier_link_redirect($url,'/produto/outro/')==='https://meudropbrasil.com/produto/outro/','relative same-host redirect supported');
foreach([['status'=>403,'contentType'=>'text/html','body'=>'Denied'],['status'=>200,'contentType'=>'application/json','body'=>'{}'],['status'=>200,'contentType'=>'text/html','body'=>'<h1>Entrar na conta</h1><form><input type="password"></form>']] as $response){$blocked=false;try{supplier_read_link($url,fn()=>$response);}catch(SupplierLinkException){$blocked=true;}link_check($blocked,'denial, unsupported format or login stops import');}
$ambiguous=false;try{supplier_html_products('<h1>Produto</h1><p>R$ 26,00 ou 3x de R$ 9,00</p>',$url);}catch(SupplierLinkException){$ambiguous=true;}link_check($ambiguous,'installment amount not guessed as product cost');
$tooLarge=false;try{supplier_html_products(str_repeat('X',2097153),$url);}catch(SupplierLinkException){$tooLarge=true;}link_check($tooLarge,'oversized page rejected');
$h2='<main><section><h1>Catálogo do fornecedor</h1><h2>Aparador de Pelos Elétrico Kemei KM-6511 Nariz Orelha Recarregavel</h2><form><p>R$ <span>26,00</span></p><input type="password" value="NEVER-RETURN"></form><li>EAN Principal: 6955549365117</li></section></main>';
$r=supplier_html_products($h2,$url);link_check($r['products'][0]['cost']===2600&&str_contains($r['products'][0]['title'],'Aparador'),'H2 product title matched to link and price text inside product form');
$privatePrice=str_replace('R$ <span>26,00</span>','Entre para consultar o preço',$h2);$r=supplier_html_products($privatePrice,$url);link_check($r['partial']===true&&$r['products'][0]['cost']===null,'public title imported as partial without fabricating a restricted price');link_check($r['products'][0]['gtin']==='6955549365117','partial read still extracts public EAN');link_check(!str_contains(json_encode($r['diagnostic']),'NEVER-RETURN'),'diagnostic contains no form values');
try{supplier_html_products('<h1>Verifique seu navegador</h1><script src="/challenge-platform/test"></script>',$url);throw new RuntimeException('Missing protection diagnosis');}catch(SupplierLinkException $e){link_check(($e->diagnostic['reason']??'')==='possible_access_check','access-check page diagnosed without attempting bypass');}
